demo_out=[r[:] for r in demo_in]; demo_out[2][2]=4; demo_out[3][2]=4

def transform(g):
    from collections import deque
    h,w=len(g),len(g[0])
    # background color = most common
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and g[ni][nj]==bg and not seen[ni][nj]:
                seen[ni][nj]=True; q.append((ni,nj))
    out=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and not seen[i][j]: out[i][j]=4
    return out

